        uint256 ltc = 1e18;
        uint256 duration = 7 days;

        // We need to simulate a lender. Use a separate address.
        address lender = address(0x1234);
        vm.deal(lender, 1 ether);

        // Pre-fund the lender with debt tokens? Actually we need an ERC20 debt token.
        // For simplicity, we'll skip creating a real loan and just test the approval function directly.
        // The property: only the lender of loanID can set approval for that loan.
        // Since we don't have a loan, we can still test the revert behavior.

        // First, ensure we have a loan at loanID 0 by creating one.
        // We'll use vm.assume to restrict loanID to 0 and set up state manually with vm.store?
        // Better: assume loanID < c.loansLength()? But loans is dynamic.
        // Simpler: just test the function with a non-existent loanID.

        // We'll use a try/catch approach: call approveTransfer from caller and check revert.
        // For reference C, non-lender must revert; for buggy M, it does not revert.

        // To create a loan, we need to call requestLoan then clearRequest.
        // But that requires actual ERC20 tokens. Instead, we can just check the revert difference directly
        // by calling approveTransfer with a random loanID.

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("approveTransfer(address,uint256)", to, loanID));

        // The reference C reverts if caller is not the lender of that loan.
